# news-image-20261124: draws the world news of Tuesday 24 November 2026.
#
# A self-contained Python 3.13 program (standard library only). It renders a
# 1024x1024 newspaper front page from scratch: a raster canvas, 1-bit bitmap
# fonts embedded as data below, a hand-rolled PNG encoder. No network, no
# clock, no randomness, no files read: two runs write byte-identical files.
#
# The seven stories were verified against Reuters / NBC Chicago / FAA
# reporting of 24 November 2026 (see the README for the source of each).
import base64
import binascii
import os
import struct
import zlib

W, H = 1024, 1024

# --- palette ---------------------------------------------------------------
PAPER = (248, 243, 231)
PANEL = (255, 253, 246)
INK = (25, 25, 25)
MUTED = (107, 98, 87)
RED = (168, 35, 42)
NAVY = (23, 54, 93)
STEEL = (58, 96, 128)
GREEN = (46, 111, 64)
TEAL = (14, 116, 118)
BORDER = (216, 208, 192)
CHIP_BG = (31, 58, 95)
CHIP_FACE = (58, 96, 150)


# --- canvas ----------------------------------------------------------------
class Canvas:
    def __init__(self, w, h, bg):
        self.w = w
        self.h = h
        self.px = bytearray(w * h * 3)
        self.fill_rect(0, 0, w, h, bg)

    def fill_rect(self, x, y, w, h, color):
        x0 = max(0, x)
        y0 = max(0, y)
        x1 = min(self.w, x + w)
        y1 = min(self.h, y + h)
        if x1 <= x0 or y1 <= y0:
            return
        row = bytes(color) * (x1 - x0)
        for yy in range(y0, y1):
            off = (yy * self.w + x0) * 3
            self.px[off:off + len(row)] = row

    def set_pixel(self, x, y, color):
        if 0 <= x < self.w and 0 <= y < self.h:
            off = (y * self.w + x) * 3
            self.px[off] = color[0]
            self.px[off + 1] = color[1]
            self.px[off + 2] = color[2]

    def hline(self, x, y, w, color, thick=1):
        self.fill_rect(x, y, w, thick, color)

    def vline(self, x, y, h, color, thick=1):
        self.fill_rect(x, y, thick, h, color)

    def rect(self, x, y, w, h, color, thick=1):
        self.hline(x, y, w, color, thick)
        self.hline(x, y + h - thick, w, color, thick)
        self.vline(x, y, h, color, thick)
        self.vline(x + w - thick, y, h, color, thick)

    def line(self, x0, y0, x1, y1, color):
        # Bresenham
        dx = abs(x1 - x0)
        dy = -abs(y1 - y0)
        sx = 1 if x0 < x1 else -1
        sy = 1 if y0 < y1 else -1
        err = dx + dy
        while True:
            self.set_pixel(x0, y0, color)
            if x0 == x1 and y0 == y1:
                return
            e2 = 2 * err
            if e2 >= dy:
                err += dy
                x0 += sx
            if e2 <= dx:
                err += dx
                y0 += sy


# --- fonts -----------------------------------------------------------------
# Font bitmap blobs generated in-session from DejaVu (free license).
CHARSET = ' !"#$%&\'()*+,-./0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ[\\]^_`abcdefghijklmnopqrstuvwxyz{|}~·—‘’“”'
FONT_BLOBS = {
    'serif60': '',
    'serif40': '',
    'sans28b': '',
    'sans24b': '',
    'sans24': '',
    'sans20': '',
    'sans18b': '',
    'sans18': '',
}

def decode_font(blob):
    raw = base64.b64decode(blob)
    ascent, descent = struct.unpack(">HH", raw[:4])
    glyphs = {}
    pos = 4
    for ch in CHARSET:
        adv, x0, y0, w, h = struct.unpack(">BbbBB", raw[pos:pos + 5])
        pos += 5
        n = ((w + 7) // 8) * h
        glyphs[ch] = (adv, x0, y0, w, h, raw[pos:pos + n])
        pos += n
    return {"ascent": ascent, "descent": descent, "glyphs": glyphs}


FONTS = {name: decode_font(blob) for name, blob in FONT_BLOBS.items()}
SPACE_ADV = {name: f["glyphs"][" "][0] for name, f in FONTS.items()}


def text_width(font_name, text):
    g = FONTS[font_name]["glyphs"]
    return sum(g[ch][0] if ch in g else g[" "][0] for ch in text)


def wrap_text(font_name, text, max_w):
    """Greedy word wrap; returns a list of lines that fit max_w."""
    g = FONTS[font_name]["glyphs"]
    space = g[" "][0]
    words = text.split(" ")
    lines, cur, cur_w = [], "", 0
    for word in words:
        ww = sum(g[ch][0] if ch in g else space for ch in word)
        add = ww if not cur else space + ww
        if cur and cur_w + add > max_w:
            lines.append(cur)
            cur, cur_w = word, ww
        else:
            cur = word if not cur else cur + " " + word
            cur_w += add
    if cur:
        lines.append(cur)
    return lines


def draw_text(cv, x, y, font_name, text, color):
    """Draw text with its ascender top at (x, y). Returns width drawn."""
    font = FONTS[font_name]
    g = font["glyphs"]
    cx = x
    for ch in text:
        glyph = g.get(ch)
        if glyph is None:
            glyph = g[" "]
        adv, gx0, gy0, w, h, bmp = glyph
        if w and h:
            rb = (w + 7) // 8
            for row in range(h):
                base = row * rb
                for col in range(w):
                    if bmp[base + col // 8] & (0x80 >> (col % 8)):
                        cv.set_pixel(cx + gx0 + col, y + gy0 + row, color)
        cx += adv
    return cx - x


def draw_text_centered(cv, cx, y, font_name, text, color):
    w = text_width(font_name, text)
    draw_text(cv, cx - w // 2, y, font_name, text, color)


# --- PNG encoder -----------------------------------------------------------
def write_png(cv, path):
    raw = bytearray()
    stride = cv.w * 3
    for y in range(cv.h):
        raw.append(0)  # filter: none
        raw += cv.px[y * stride:(y + 1) * stride]
    compressed = zlib.compress(bytes(raw), 9)

    def chunk(kind, data):
        out = struct.pack(">I", len(data)) + kind + data
        return out + struct.pack(">I", binascii.crc32(kind + data) & 0xFFFFFFFF)

    ihdr = struct.pack(">IIBBBBB", cv.w, cv.h, 8, 2, 0, 0, 0)
    png = b"\x89PNG\r\n\x1a\n"
    png += chunk(b"IHDR", ihdr)
    png += chunk(b"IDAT", compressed)
    png += chunk(b"IEND", b"")
    with open(path, "wb") as f:
        f.write(png)
    return len(png)

# --- content: verified 24 November 2026 news --------------------------------
