# --- drawing ----------------------------------------------------------------
def draw_chip(cv, x, y, size):
    """A microchip pictogram: dark body, pins on four sides, circuit traces."""
    pad = size // 6
    body = size - 2 * pad
    pin_len = pad - 4
    pin_w = max(4, body // 8)
    # pins
    for i in range(4):
        off = pad + i * (body // 4) + (body // 8 - pin_w // 2)
        cv.fill_rect(x + off, y + 4, pin_w, pin_len, INK)
        cv.fill_rect(x + off, y + size - 4 - pin_len, pin_w, pin_len, INK)
        cv.fill_rect(x + 4, y + off, pin_len, pin_w, INK)
        cv.fill_rect(x + size - 4 - pin_len, y + off, pin_len, pin_w, INK)
    # body
    cv.fill_rect(x + pad, y + pad, body, body, CHIP_BG)
    cv.rect(x + pad, y + pad, body, body, INK, 2)
    inner = body // 2
    cv.fill_rect(x + pad + (body - inner) // 2, y + pad + (body - inner) // 2,
                 inner, inner, CHIP_FACE)
    cv.rect(x + pad + (body - inner) // 2, y + pad + (body - inner) // 2,
            inner, inner, PAPER, 2)
    # traces from inner square to the body edges
    mid = x + pad + body // 2
    midy = y + pad + body // 2
    half = inner // 2
    for dx, dy in ((0, -1), (0, 1), (-1, 0), (1, 0)):
        cv.line(mid + dx * half, midy + dy * half,
                mid + dx * (body // 2 - 2), midy + dy * (body // 2 - 2), PAPER)
    # corner dots
    for dx in (-1, 1):
        for dy in (-1, 1):
            cx = mid + dx * (body // 2 - 2)
            cy = midy + dy * (body // 2 - 2)
            cv.fill_rect(cx - 3, cy - 3, 7, 7, RED)


def draw_tag(cv, x, y, text, color):
    w = text_width("sans18b", text) + 20
    cv.fill_rect(x, y, w, 24, color)
    draw_text(cv, x + 10, y + 4, "sans18b", text, PAPER)
    return w


def draw_story_cell(cv, x, y, w, h, story):
    cv.fill_rect(x, y, w, h, PANEL)
    cv.rect(x, y, w, h, BORDER, 1)
    draw_tag(cv, x + 12, y + 10, story["tag"], story["color"])
    lines = wrap_text("sans28b", story["headline"], w - 24)
    ly = y + 42
    for ln in lines[:2]:
        draw_text(cv, x + 12, ly, "sans28b", ln, INK)
        ly += 33
    slines = wrap_text("sans20", story["summary"], w - 24)
    sy = y + 106
    for ln in slines[:3]:
        draw_text(cv, x + 12, sy, "sans20", ln, (58, 52, 44))
        sy += 23


def render():
    cv = Canvas(W, H, PAPER)
    # masthead rules
    cv.hline(40, 30, 944, INK, 3)
    cv.hline(40, 36, 944, INK, 1)
    # masthead
    draw_text_centered(cv, 512, 48, "serif60", "THE WORLD IN ONE DAY", INK)
    draw_text_centered(cv, 512, 116, "sans24b", "TUESDAY, 24 NOVEMBER 2026", RED)
    draw_text_centered(
        cv, 512, 146, "sans18",
        "SEVEN STORIES FROM AROUND THE WORLD \u2014 ALL FIRST REPORTED ON 24 NOVEMBER 2026",
        MUTED)
    cv.hline(40, 172, 944, NAVY, 4)

    # lead story panel
    lx, ly, lw, lh = 40, 186, 944, 208
    cv.fill_rect(lx, ly, lw, lh, PANEL)
    cv.rect(lx, ly, lw, lh, BORDER, 1)
    cv.fill_rect(lx, ly, 8, lh, RED)
    draw_text(cv, lx + 24, ly + 14, "sans18b", LEAD["kicker"], RED)
    sw = text_width("sans18b", LEAD["source"])
    draw_text(cv, lx + lw - 16 - sw, ly + 14, "sans18b", LEAD["source"], MUTED)
    lines = wrap_text("serif40", LEAD["headline"], 700)
    hy = ly + 44
    for ln in lines[:2]:
        draw_text(cv, lx + 24, hy, "serif40", ln, INK)
        hy += 46
    slines = wrap_text("sans24", LEAD["summary"], 700)
    sy = ly + 140
    for ln in slines[:2]:
        draw_text(cv, lx + 24, sy, "sans24", ln, (58, 52, 44))
        sy += 30
    draw_chip(cv, lx + lw - 176, ly + 32, 144)

    # grid of six stories: 2 columns x 3 rows
    cw, ch, gap = 464, 175, 16
    for i, story in enumerate(STORIES):
        cx = 40 + (i % 2) * (cw + gap)
        cy = 406 + (i // 2) * (ch + 12)
        draw_story_cell(cv, cx, cy, cw, ch, story)

    # footer
    cv.hline(40, 968, 944, INK, 1)
    draw_text_centered(
        cv, 512, 978, "sans18",
        "Sources: Reuters \u00b7 NBC Chicago \u00b7 FAA \u2014 All seven stories first reported on Tuesday, 24 November 2026.",
        MUTED)
    return cv


def main():
    out_dir = os.environ.get("MAKEFUN_OUTPUT_DIR", "/output")
    os.makedirs(out_dir, exist_ok=True)
    cv = render()
    n = write_png(cv, os.path.join(out_dir, "entry.png"))
    print(f"wrote entry.png ({n} bytes, {W}x{H})")


if __name__ == "__main__":
    main()
